  function VoiceMicButton({ onTranscribed, title = "Speak instead of typing" }) {
    const [recording, setRecording] = useState(false);
    const [busy, setBusy] = useState(false);
    const [error, setError] = useState("");
    const recorderRef = useRef(null);
    const chunksRef = useRef([]);
    const { level: talkLevel, attach: attachTalkLevel, detach: detachTalkLevel } = useTalkingLevel();

    async function startRecording() {
      setError("");
      if (!navigator.mediaDevices || !window.MediaRecorder) {
        setError("Voice input isn't supported in this browser.");
        return;
      }
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        attachTalkLevel(stream);
        const recorder = new MediaRecorder(stream);
        chunksRef.current = [];
        recorder.ondataavailable = (ev) => { if (ev.data && ev.data.size > 0) chunksRef.current.push(ev.data); };
        recorder.onstop = async () => {
          stream.getTracks().forEach((t) => t.stop());
          detachTalkLevel();
          const blob = new Blob(chunksRef.current, { type: recorder.mimeType || "audio/webm" });
          await transcribe(blob);
        };
        recorderRef.current = recorder;
        recorder.start();
        setRecording(true);
      } catch (e) {
        setError("Couldn't access the microphone — check your browser's permission.");
      }
    }

    function stopRecording() {
      if (recorderRef.current && recording) {
        recorderRef.current.stop();
        setRecording(false);
      }
    }

    async function transcribe(blob) {
      if (!sb) { setError("Backend not configured yet."); return; }
      setBusy(true);
      setError("");
      try {
        const audio = await blobToBase64(blob);
        const { data, error: err } = await sb.functions.invoke("voice-transcribe", {
          body: { audio, mimeType: blob.type || "audio/webm" }
        });
        if (err || !data || data.error) {
          setError("Couldn't understand that — try again.");
        } else if (data.text && data.text.trim()) {
          onTranscribed(data.text.trim());
        } else {
          setError("Didn't catch anything — try again.");
        }
      } catch (e) {
        setError("Couldn't understand that — try again.");
      }
      setBusy(false);
    }

    return e("span", { style: { display: "inline-flex", alignItems: "center", gap: 6 } },
      e("button", {
        type: "button",
        title,
        "aria-label": title,
        // Never steal focus from a sibling input on click — several call sites (EditableStat,
        // the exercise picker's dropdown) auto-save on blur, and this button living right next
        // to those fields must not accidentally trigger that.
        onMouseDown: (ev) => ev.preventDefault(),
        style: {
          flexShrink: 0,
          display: "flex", alignItems: "center", gap: 5,
          background: recording ? C.criticalSoft : C.brandSoft,
          border: `1px solid ${recording ? C.critical : C.cardBorderStrong}`,
          borderRadius: 9,
          padding: "0 12px",
          height: 44,
          color: recording ? C.critical : busy ? C.ink3 : C.brand,
          fontFamily: "'Inter', sans-serif", fontWeight: 600, fontSize: 12,
          cursor: busy ? "default" : "pointer"
        },
        disabled: busy,
        onClick: recording ? stopRecording : startRecording
      }, recording ? e(TalkingTrainerEmoji, { level: talkLevel, size: 16 }) : busy ? e(VoiceLoadingDots, { size: 5, color: C.ink3 }) : e(Icon, { name: "mic", size: 15 }), recording ? "Stop" : busy ? "Working…" : "Speak"),
      error && e("span", { style: { ...styles.inlineError, fontSize: 11 } }, error)
    );
  }

  // One mic button that fills an entire New Exercise form from a single
  // spoken note — say it in English, Arabic, Lebanese dialect, or a mix of
  // both, and it comes back as clean English: workout title (if mentioned),
  // exercise name, and every set of reps/weight/rest. Replaces the old
  // pattern of a separate "Speak" button per field. Talks to the
  // "voice-log-entry" Supabase Edge Function (translate → structure), as
  // opposed to VoiceMicButton above, which only transcribes into one field.
  function SmartVoiceEntryButton({ onParsed, label = "Speak your set — exercise, sets, weight" }) {
    const [recording, setRecording] = useState(false);
    const [busy, setBusy] = useState(false);
    const [error, setError] = useState("");
    const [heardText, setHeardText] = useState("");
    const recorderRef = useRef(null);
    const chunksRef = useRef([]);
    const { level: talkLevel, attach: attachTalkLevel, detach: detachTalkLevel } = useTalkingLevel();

    async function startRecording() {
      setError(""); setHeardText("");
      if (!navigator.mediaDevices || !window.MediaRecorder) {
        setError("Voice input isn't supported in this browser.");
        return;
      }
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        attachTalkLevel(stream);
        const recorder = new MediaRecorder(stream);
        chunksRef.current = [];
        recorder.ondataavailable = (ev) => { if (ev.data && ev.data.size > 0) chunksRef.current.push(ev.data); };
        recorder.onstop = async () => {
          stream.getTracks().forEach((t) => t.stop());
          detachTalkLevel();
          const blob = new Blob(chunksRef.current, { type: recorder.mimeType || "audio/webm" });
          await sendForParsing(blob);
        };
        recorderRef.current = recorder;
        recorder.start();
        setRecording(true);
      } catch (e) {
        setError("Couldn't access the microphone — check your browser's permission.");
      }
    }

    function stopRecording() {
      if (recorderRef.current && recording) {
        recorderRef.current.stop();
        setRecording(false);
      }
    }

    async function sendForParsing(blob) {
      if (!sb) { setError("Backend not configured yet."); return; }
      setBusy(true);
      setError("");
      try {
        const audio = await blobToBase64(blob);
        let exerciseNames = [];
        try {
          const catalog = await fetchExerciseCatalogForPicker();
          exerciseNames = (catalog || []).map((x) => x.name).filter(Boolean);
        } catch (e) { /* fine without it — parsing just falls back to plain-English naming */ }
        const { data, error: err } = await sb.functions.invoke("voice-log-entry", {
          body: { audio, mimeType: blob.type || "audio/webm", exerciseNames }
        });
        if (err || !data || data.error) {
          setError("Couldn't understand that — try again.");
        } else {
          setHeardText(data.heardText || "");
          onParsed(data);
        }
      } catch (e) {
        setError("Couldn't understand that — try again.");
      }
      setBusy(false);
    }

    return e("div", { style: { marginBottom: 14 } },
      e("button", {
        type: "button",
        onMouseDown: (ev) => ev.preventDefault(),
        onClick: recording ? stopRecording : startRecording,
        disabled: busy,
        style: {
          display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          width: "100%", padding: "13px 16px", borderRadius: 12,
          background: recording ? C.criticalSoft : C.brandSoft,
          border: `1.5px solid ${recording ? C.critical : C.brand}`,
          color: recording ? C.critical : C.brand,
          fontFamily: "'Inter', sans-serif", fontWeight: 700, fontSize: 13.5,
          cursor: busy ? "default" : "pointer"
        }
      },
        recording ? e(TalkingTrainerEmoji, { level: talkLevel, size: 19 }) : busy ? e(VoiceLoadingDots, { size: 6, color: C.brand }) : e(Icon, { name: "mic", size: 17 }),
        recording ? "Stop — I'm done" : busy ? "Got it — working out the details…" : label
      ),
      error && e("div", { style: { ...styles.inlineError, marginTop: 6 } }, error),
      heardText && !error && e("div", { style: { fontSize: 11.5, color: C.ink3, marginTop: 6, fontStyle: "italic" } }, `Heard: "${heardText}"`)
    );
  }

  // Small always-visible icon using the RepDB match above — falls back to a
  // plain dumbbell glyph (still themed/consistent) for exercises not in
  // RepDB's 601-exercise set, so every row still looks uniform.
  // Sept 13 2026, Jimmy: "i see it but cant open it" — tapping the icon
  // itself used to do nothing; onOpen (wired to the paired ExerciseDemo's
  // own open() below) lets tapping the icon open the same big view "Show
  // demo" opens, instead of only working from that separate button.
  function ExerciseIcon({ name, size = 40, onOpen }) {
    const [icon, setIcon] = useState(exerciseIconMemCache[exerciseGifKey(name)] || null);
    useEffect(() => {
      let cancelled = false;
      const key = exerciseGifKey(name);
      if (key in exerciseIconMemCache) { setIcon(exerciseIconMemCache[key]); return; }
      fetchExerciseIcon(name).then((r) => { if (!cancelled) setIcon(r); });
      return () => { cancelled = true; };
    }, [name]);
    const iconUrl = icon && icon.iconUrl;
    return e("div", {
      onClick: onOpen,
      role: onOpen ? "button" : undefined,
      "aria-label": onOpen ? `Show ${name} demo` : undefined,
      style: {
        width: size, height: size, borderRadius: "50%", flexShrink: 0, overflow: "hidden",
        background: C.subtleFill, border: `1px solid ${C.cardBorder}`,
        display: "flex", alignItems: "center", justifyContent: "center",
        cursor: onOpen ? "pointer" : "default"
      }
    },
      iconUrl
        ? e("img", { src: iconUrl, alt: "", style: { width: "100%", height: "100%", objectFit: "cover" } })
        : e(Icon, { name: "dumbbell", size: Math.round(size * 0.42), color: C.ink3 })
    );
  }

  // Sept 13 2026, Jimmy: "cant open it" (re: the small icon) — forwardRef +
  // an exposed open() lets ExerciseIcon (a separate sibling component) open
  // this same panel, not just its own "Show demo" button.
  const ExerciseDemo = React.forwardRef(function ExerciseDemo({ name }, ref) {
    const [open, setOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [result, setResult] = useState(exerciseDemoVisualMemCache[exerciseGifKey(name)] || null);
    const [checked, setChecked] = useState(exerciseGifKey(name) in exerciseDemoVisualMemCache);
    const [showManual, setShowManual] = useState(false);
    const [manualUrl, setManualUrl] = useState("");
    const [muscles, setMuscles] = useState(exerciseMusclesMemCache[exerciseGifKey(name)] || null);
    const [musclesChecked, setMusclesChecked] = useState(exerciseGifKey(name) in exerciseMusclesMemCache);
    const [showMuscleForm, setShowMuscleForm] = useState(false);
    const [muscleFormPrimary, setMuscleFormPrimary] = useState("");
    const [muscleFormSecondary, setMuscleFormSecondary] = useState([]);

    async function handleSaveMuscleTags() {
      if (!muscleFormPrimary) return;
      await saveManualExerciseMuscles(name, muscleFormPrimary, muscleFormSecondary);
      setMuscles({ primary: muscleFormPrimary, secondary: muscleFormSecondary });
      setShowMuscleForm(false);
    }

    async function handleOpen() {
      const next = !open;
      setOpen(next);
      if (next && !checked) {
        setLoading(true);
        const r = await fetchExerciseDemoVisual(name);
        setResult(r);
        setChecked(true);
        setLoading(false);
      }
      // Independent of the demo-photo lookup above (and never blocked by its
      // loading state) — a manual gif-link override shouldn't hide the muscle
      // diagram, since that always comes straight from the catalog.
      if (next && !musclesChecked) {
        fetchExerciseMuscles(name).then((m) => { setMuscles(m); setMusclesChecked(true); });
      }
    }
    React.useImperativeHandle(ref, () => ({ open: handleOpen }));

    async function handleSaveManual() {
      if (!manualUrl.trim()) return;
      await saveManualExerciseGif(name, manualUrl.trim());
      setResult({ imageUrl: manualUrl.trim(), imageUrl2: null, isManual: true, matchedName: null });
      setShowManual(false);
      setManualUrl("");
    }

    const imgUrl = result && result.imageUrl;
    const imgUrl2 = result && result.imageUrl2;
    const isManual = result && result.isManual;
    const matchedName = result && result.matchedName;
    const looksOff = matchedName && exerciseGifKey(matchedName) !== exerciseGifKey(name);
    const ytEmbed = youtubeEmbedUrl(imgUrl);

    // Same "looks like it's moving" trick the old real-photo demo used —
    // flip between RepDB's paired start/peak illustration frames when both
    // are available for this exercise (most are; a few only have one pose).
    const [frameOn, setFrameOn] = useState(false);
    useEffect(() => {
      if (!open || ytEmbed || !imgUrl2) return;
      const id = setInterval(() => setFrameOn((v) => !v), 700);
      return () => clearInterval(id);
    }, [open, ytEmbed, imgUrl2]);
    const displaySrc = imgUrl2 && frameOn ? imgUrl2 : imgUrl;

    return e("div", { style: { marginTop: open ? 8 : 0 } },
      e("button", { style: styles.demoToggleBtn, onClick: handleOpen },
        e(Icon, { name: "play", size: 12 }), open ? "Hide demo" : "Show demo"),
      open && e("div", { style: styles.demoPanel },
        loading && e("span", { style: styles.demoNote }, "Looking up a demo…"),
        !loading && imgUrl && e("div", null,
          ytEmbed
            ? e("iframe", { src: ytEmbed, style: { ...styles.demoImg, height: 150, border: "none" }, allow: "autoplay; encrypted-media", allowFullScreen: true })
            : e("img", { src: displaySrc, alt: `${name} demo`, style: styles.demoImg }),
          // Same consistent RepDB style everywhere now — only call out a
          // "matched" name when it's an automatic match that might be wrong;
          // a trainer's own manually-added link needs no such caveat.
          !isManual && matchedName && e("span", { style: { ...styles.demoNote, display: "block", marginTop: 6 } },
            "Matched: “", matchedName, "”", looksOff ? " — does this look right?" : ""),
          !showManual && e("button", { style: styles.demoLinkBtn, onClick: () => setShowManual(true) },
            !isManual && looksOff ? "That's not right — add the correct link" : "Not right? Add your own link")
        ),
        !loading && !imgUrl && !showManual && e("div", null,
          e("span", { style: styles.demoNote }, "No demo found for “", name, "”."),
          e("div", { style: { display: "flex", gap: 14, marginTop: 4 } },
            e("a", { href: youtubeSearchUrl(name), target: "_blank", rel: "noopener noreferrer", style: { ...styles.demoLinkBtn, marginTop: 0 } }, "Search YouTube ↗"),
            e("button", { style: { ...styles.demoLinkBtn, marginTop: 0 }, onClick: () => setShowManual(true) }, "+ Add your own link")
          )
        ),
        !loading && showManual && e("div", { style: { display: "flex", gap: 8, marginTop: 6, flexWrap: "wrap" } },
          e("input", {
            style: { ...styles.input, flex: 1, minWidth: 160 }, placeholder: "Paste a YouTube link or direct GIF/image URL",
            value: manualUrl, onChange: (ev) => setManualUrl(ev.target.value)
          }),
          e("button", { style: styles.saveBtn, onClick: handleSaveManual }, "Save")
        ),
        muscles && e(MuscleDiagram, { primary: muscles.primary, secondary: muscles.secondary }),
        // Plenty of exercises aren't in the free dataset at all — same reason
        // they have no demo photo also means no muscle tags. Let whoever's
        // looking tag it once; after that, everyone who looks this exercise
        // up gets the diagram too, same as a manually-added demo link.
        !loading && musclesChecked && !muscles && !showMuscleForm && e("button", { style: styles.demoLinkBtn, onClick: () => setShowMuscleForm(true) }, "+ Tag which muscles this works"),
        showMuscleForm && e("div", { style: { marginTop: 8, display: "flex", flexDirection: "column", gap: 8 } },
          e("select", {
            style: styles.input, value: muscleFormPrimary,
            onChange: (ev) => { setMuscleFormPrimary(ev.target.value); setMuscleFormSecondary((prev) => prev.filter((k) => k !== ev.target.value)); }
          },
            e("option", { value: "" }, "Primary muscle…"),
            MUSCLE_DISPLAY_ORDER.map((k) => e("option", { key: k, value: k }, PRIMARY_MUSCLE_LABEL[k]))
          ),
          e("span", { style: styles.demoNote }, "Secondary (optional) — tap any that also work:"),
          e("div", { style: { display: "flex", flexWrap: "wrap", gap: 6 } },
            MUSCLE_DISPLAY_ORDER.filter((k) => k !== muscleFormPrimary).map((k) => e("button", {
              key: k, type: "button",
              style: {
                ...styles.demoToggleBtn, marginTop: 0,
                ...(muscleFormSecondary.includes(k) ? { background: C.brandSoft, color: C.brand, borderColor: C.brand } : {})
              },
              onClick: () => setMuscleFormSecondary((prev) => prev.includes(k) ? prev.filter((x) => x !== k) : [...prev, k])
            }, PRIMARY_MUSCLE_LABEL[k]))
          ),
          e("div", { style: { display: "flex", gap: 8 } },
            e("button", {
              style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(!muscleFormPrimary ? styles.btnDisabled : {}) },
              disabled: !muscleFormPrimary, onClick: handleSaveMuscleTags
            }, "Save"),
            e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => setShowMuscleForm(false) }, "Cancel")
          )
        )
      )
    );
  });

  // Sept 16 2026, Jimmy: Attack Protection — renders Cloudflare's Turnstile
  // widget (see TURNSTILE_SITE_KEY above). No-ops entirely (renders nothing,
  // never calls onToken) when TURNSTILE_ENABLED is false, so it's safe to
  // mount unconditionally once TURNSTILE_ENABLED flips on. `onToken` fires
  // with a fresh token on success and with "" on expiry/error, so the form
  // can block submit until a real token is present — a token is single-use,
  // so the parent bumps `resetKey` after every submit attempt to force a
  // fresh widget for the next one.
  function TurnstileWidget({ onToken, resetKey, theme = "dark" }) {
    const containerRef = useRef(null);
    const widgetIdRef = useRef(null);
    // Sept 16 2026, Jimmy: an ad blocker or privacy extension blocking
    // challenges.cloudflare.com (not rare — some block it by default), or
    // just a bad connection, would otherwise leave the submit button
    // silently disabled forever with no explanation. 8s without
    // window.turnstile showing up flips this so the form can say what's
    // actually wrong instead of looking broken.
    const [loadFailed, setLoadFailed] = useState(false);

    useEffect(() => {
      if (!TURNSTILE_ENABLED) return;
      let cancelled = false;
      let pollId = null;
      let timeoutId = null;

      function renderWidget() {
        if (cancelled || !containerRef.current || !window.turnstile) return;
        setLoadFailed(false);
        if (widgetIdRef.current) {
          try { window.turnstile.remove(widgetIdRef.current); } catch (e) {}
        }
        containerRef.current.innerHTML = "";
        widgetIdRef.current = window.turnstile.render(containerRef.current, {
          sitekey: TURNSTILE_SITE_KEY,
          theme,
          callback: (token) => { if (!cancelled) onToken(token); },
          "expired-callback": () => { if (!cancelled) onToken(""); },
          "error-callback": () => { if (!cancelled) onToken(""); }
        });
      }

      if (window.turnstile) {
        renderWidget();
      } else {
        // api.js in <head> loads async/defer — poll briefly instead of
        // assuming it's already there by the time this mounts.
        pollId = setInterval(() => {
          if (window.turnstile) { clearInterval(pollId); renderWidget(); }
        }, 150);
        timeoutId = setTimeout(() => {
          if (!cancelled && !window.turnstile) setLoadFailed(true);
        }, 8000);
      }

      return () => {
        cancelled = true;
        if (pollId) clearInterval(pollId);
        if (timeoutId) clearTimeout(timeoutId);
        if (widgetIdRef.current) {
          try { window.turnstile.remove(widgetIdRef.current); } catch (e) {}
        }
      };
    }, [resetKey]);

    if (!TURNSTILE_ENABLED) return null;
    return e(React.Fragment, null,
      e("div", { ref: containerRef, style: { margin: "14px 0 4px", display: "flex", justifyContent: "center" } }),
      loadFailed && e("p", { style: { fontSize: 11.5, color: C.ink3, textAlign: "center", margin: "0 0 4px" } },
        "Verification didn't load — check your connection or disable any ad blocker for this page, then reload."
      )
    );
  }

  // Sept 8 2026, Jimmy: weight per exercise, editable both by the trainer
  // (a target/prescribed weight, via the full edit form — see showWeightField
  // on ExerciseForm) and by the client themselves (what they actually lifted,
  // tracked week to week since ClientCustomProgramCard's rows are already
  // real per-week rows, not a repeating template). canEditWeight is only ever
  // passed true from the client's own view of their program — a lightweight
  // inline editor for just this one field, so a client can log progress
  // without needing edit rights over the exercise/sets/reps/day structure.
  function ProgramExerciseRow({ ex, canManage, onEdit, onDelete, onDuplicate, canEditWeight, onWeightSave, onLogWeight, justDuplicated, rowRef }) {
    const [editingWeight, setEditingWeight] = useState(false);
    const [weightDraft, setWeightDraft] = useState(ex.weight || "");
    function commitWeight() {
      setEditingWeight(false);
      const trimmed = weightDraft.trim();
      if (trimmed !== (ex.weight || "")) onWeightSave(ex.id, trimmed);
    }
    // Sept 13 2026, Jimmy: "cant open it" — lets tapping the small icon
    // below open the same ExerciseDemo panel as its own "Show demo" button.
    const demoRef = useRef(null);
    return e("div", {
        ref: rowRef,
        style: {
          ...styles.programExerciseRow,
          transition: "background-color 0.6s ease, border-color 0.6s ease",
          display: "flex", alignItems: "flex-start", gap: 10,
          ...(justDuplicated ? { background: C.brandTint || "rgba(62,123,250,0.12)", borderColor: C.brand } : {})
        }
      },
      // Sept 12 2026, Jimmy: wants every exercise to show a small, always-
      // visible consistent-style icon (like Hevy) instead of only the
      // tap-to-reveal "Show demo" photo below — this is a separate, simpler
      // layer on top; ExerciseDemo's richer real-photo/muscle-diagram flow
      // is untouched further down in this same row.
      e(ExerciseIcon, { name: ex.exercise, size: 42, onOpen: () => demoRef.current && demoRef.current.open() }),
      e("div", { style: { flex: 1, minWidth: 0 } },
      e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 } },
        e("div", { style: { display: "flex", alignItems: "center", gap: 6, minWidth: 0 } },
          e("span", { style: styles.exerciseName }, ex.exercise),
          // Sept 11 2026, Jimmy: "i cant press the copy and see the paste" —
          // duplicating worked, it just gave no visible sign it worked. This
          // badge + the highlighted row above (justDuplicated) make the new
          // "pasted" copy obvious for a couple seconds right where it landed.
          justDuplicated && e("span", { style: { fontSize: 10.5, fontWeight: 700, color: C.brand, background: C.brandTint || "rgba(62,123,250,0.12)", border: `1px solid ${C.brand}`, borderRadius: 999, padding: "2px 7px", flexShrink: 0 } }, "Copied")
        ),
        canManage && e("div", { style: { display: "flex", gap: 2, flexShrink: 0 } },
          // Sept 9 2026, Jimmy: a quick way to clone one exercise (e.g. to
          // add a near-identical variant on the same day, then just tweak
          // the copy) — onDuplicate is optional so this stays a no-op
          // anywhere it isn't wired up.
          onDuplicate && e("button", { style: styles.editBtn, onClick: () => onDuplicate(ex), "aria-label": "Duplicate exercise", title: "Duplicate this exercise" }, e(Icon, { name: "copy", size: 13 })),
          e("button", { style: styles.editBtn, onClick: () => onEdit(ex), "aria-label": "Edit exercise" }, e(Icon, { name: "edit", size: 13 })),
          e("button", { style: styles.deleteBtn, onClick: () => onDelete(ex.id), "aria-label": "Delete exercise" }, e(Icon, { name: "trash", size: 13 }))
        )
      ),
      e("div", { style: { display: "flex", flexWrap: "wrap", gap: 6, marginTop: 6, alignItems: "center" } },
        // Sept 11 2026, Jimmy: "one option to add one weight theres no like
        // for each set" — an exercise saved with the new per-set grid shows
        // one chip per set (its own reps-or-seconds and its own weight),
        // same look as the Log tab's own exercise chips, instead of one
        // combined "3 × 8" summary chip for the whole exercise.
        Array.isArray(ex.sets_detail) && ex.sets_detail.length
          ? ex.sets_detail.map((s, i) => e(React.Fragment, { key: i },
              e("span", { style: styles.setChip },
                e("span", { style: styles.setChipReps }, s.isTimed ? (s.duration != null ? s.duration : s.reps) : s.reps),
                s.isTimed ? "s" : " × ",
                s.isTimed ? null : (s.isBodyweight ? "Bodyweight" : `${s.weight}kg`)
              ),
              s.rest ? e(RestTimerChip, { seconds: s.rest }) : null
            ))
          : e(React.Fragment, null,
              (ex.sets || ex.reps) && e("span", { style: styles.setChip }, ex.sets ? e("span", { style: styles.setChipReps }, ex.sets) : null, ex.sets && ex.reps ? " × " : "", ex.reps || ""),
              e(RestTimerChip, { seconds: ex.rest_seconds }),
              // Legacy quick-edit chip — only for exercises saved before the
              // per-set grid (no sets_detail), so a client/trainer can still
              // touch up an old row's single weight string in place. New
              // exercises set weight per set right in the edit form instead.
              canEditWeight && (
                editingWeight
                  ? e("input", {
                      autoFocus: true, type: "text", inputMode: "decimal", placeholder: "e.g. 70x70x90", style: { ...styles.input, width: 120, padding: "4px 8px", fontSize: 13 },
                      value: weightDraft, onChange: (ev) => setWeightDraft(ev.target.value),
                      onBlur: commitWeight, onKeyDown: (ev) => { if (ev.key === "Enter") commitWeight(); if (ev.key === "Escape") { setWeightDraft(ex.weight || ""); setEditingWeight(false); } }
                    })
                  : e("span", { style: { ...styles.setChip, cursor: "pointer", borderStyle: "dashed" }, onClick: () => { setWeightDraft(ex.weight || ""); setEditingWeight(true); }, title: "Tap to log the weight used per set — e.g. 70x70x90" }, ex.weight ? `${ex.weight} kg` : "+ Log weight")
              )
            ),
        // Sept 14 2026, Jimmy: "track the weight when the client buy a
        // program... and also if he has a trainer" — a client-facing way to
        // record what they actually lifted TODAY for this exercise, whether
        // it's a bought/ready program or one a trainer assigned. Unlike the
        // legacy "+ Log weight" chip above (which just overwrites this row's
        // own weight field — fine for a trainer-owned custom program row,
        // but wrong for a shared catalog program row every buyer reads
        // from), this opens a small form that writes a brand new DATED entry
        // into the client's own workout log (same table/shape as the Log
        // tab), pre-filled from this exercise's sets — so weight logged here
        // shows up automatically in the client's existing progress chart and
        // PR badges on the Log tab, week over week, no matter which kind of
        // program it came from.
        // Sept 15 2026, Jimmy: "just keep the log weight not the no weight
        // no log" — dropped the per-exercise "No weight to log" opt-out
        // (and its toggle in ExerciseForm/ProgramSetsForm below); Log
        // weight now always shows whenever onLogWeight is passed in,
        // regardless of any no_weight_log value still sitting on old rows.
        onLogWeight && e("button", {
          style: { ...styles.setChip, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 4, color: C.brand, borderColor: withAlpha(C.brand, 0.35), background: "none" },
          onClick: () => onLogWeight(ex),
          title: "Log the weight you used for this exercise today"
        }, e(Icon, { name: "dumbbell", size: 11, strokeWidth: 2.5 }), "Log weight")
      ),
      ex.notes && e("p", { style: { ...styles.profileGoalText, marginTop: 6 } }, ex.notes),
      e(ExerciseDemo, { name: ex.exercise, ref: demoRef })
      )
    );
  }

  // Sept 14 2026, Jimmy: the sheet behind every exercise's new "Log weight"
  // button (ProgramExerciseRow, onLogWeight) — lets a client record what
  // they actually lifted TODAY for one exercise from their program, whether
  // it's a bought/ready program (no trainer) or one a trainer assigned.
  // Pre-fills the reps/seconds and rest straight from the program's own
  // sets_detail (or, for an older row with no sets_detail, from its plain
  // sets/reps summary) so the client only has to type in the weight per
  // set. Saves straight into workout_entries — the exact same table/shape
  // the Log tab itself writes to — so it shows up immediately in the
  // client's existing progress chart and PR badges there, week over week,
  // with no separate tracking system to maintain.
  function LogProgramWeightModal({ ex, clientId, clientName, contextLabel, onClose, onSaved }) {
    const fromDetail = Array.isArray(ex.sets_detail) && ex.sets_detail.length > 0;
    const isTimed = fromDetail && ex.sets_detail.some((s) => s.isTimed);
    const isBodyweight = fromDetail && ex.sets_detail.some((s) => s.isBodyweight);
    const [rows, setRows] = useState(() => (
      fromDetail
        ? ex.sets_detail.map((s) => ({
            repsOrSeconds: String(isTimed ? (s.duration != null ? s.duration : s.reps) : s.reps),
            weight: isBodyweight ? "0" : "",
            rest: s.rest != null ? s.rest : null
          }))
        : Array.from({ length: Math.max(1, Number(ex.sets) || 1) }, () => ({
            repsOrSeconds: String(ex.reps || ""),
            weight: "",
            rest: ex.rest_seconds != null ? ex.rest_seconds : null
          }))
    ));
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    const [saved, setSaved] = useState(false);

    function updateWeight(idx, val) {
      setRows((prev) => prev.map((r, i) => (i === idx ? { ...r, weight: val } : r)));
    }

    async function handleSave() {
      if (!sb) { setError("Backend not configured yet."); return; }
      const cleanSets = rows.map((r) => {
        const reps = Number(r.repsOrSeconds);
        const weight = isBodyweight ? 0 : Number(r.weight);
        return isTimed
          ? { duration: reps, weight, rest: r.rest, isTimed: true, ...(isBodyweight ? { isBodyweight: true } : {}) }
          : { reps, weight, rest: r.rest, ...(isBodyweight ? { isBodyweight: true } : {}) };
      }).filter((s) => (isTimed ? s.duration > 0 : s.reps > 0) && !Number.isNaN(s.weight) && s.weight >= 0);
      if (cleanSets.length === 0) { setError(isBodyweight ? "Something went wrong with this exercise's sets." : "Enter the weight you used for at least one set."); return; }
      setSaving(true); setError("");
      const payload = {
        date: todayISO(),
        exercise: ex.exercise,
        muscle_group: guessMuscleGroup(ex.exercise),
        workout_title: contextLabel || null,
        sets: cleanSets,
        client_name: clientName,
        client_id: clientId || null
      };
      const { data, error: err } = await sb.from("workout_entries").insert([payload]).select();
      setSaving(false);
      if (err || !data) { setError(`Couldn't save that. Try again.${err && err.message ? ` (${err.message})` : ""}`); return; }
      setSaved(true);
      if (onSaved) onSaved(data[0]);
      setTimeout(onClose, 900);
    }

    return e("div", { style: styles.overlay, onClick: onClose },
      e("div", { style: { ...styles.sheet, maxWidth: 380 }, onClick: (ev) => ev.stopPropagation() },
        e("div", { style: styles.sheetHeader },
          e("span", { style: styles.sheetTitle }, ex.exercise),
          e("button", { style: styles.closeBtn, onClick: onClose, "aria-label": "Close" }, e(Icon, { name: "x", size: 18 }))
        ),
        contextLabel && e("p", { style: { margin: "-8px 0 12px", fontSize: 11.5, color: C.ink3 } }, contextLabel),
        e("p", { style: { margin: "0 0 12px", fontSize: 12.5, color: C.ink2 } },
          isBodyweight ? "Log today's reps for this bodyweight move." : `Enter what you actually ${isTimed ? "held" : "lifted"} today, per set.`),
        e("div", { style: { display: "flex", flexDirection: "column", gap: 8 } },
          rows.map((r, i) => e("div", { key: i, style: { display: "flex", alignItems: "center", gap: 8 } },
            e("span", { style: { ...styles.setChip, flexShrink: 0 } }, `${r.repsOrSeconds}${isTimed ? "s" : " reps"}`),
            !isBodyweight && e("input", {
              type: "text", inputMode: "decimal", placeholder: "kg", autoFocus: i === 0,
              style: { ...styles.input, flex: 1, padding: "8px 10px", fontSize: 14 },
              value: r.weight, onChange: (ev) => updateWeight(i, ev.target.value)
            })
          ))
        ),
        error && e("div", { style: { ...styles.errorBanner, marginTop: 10 } }, e(Icon, { name: "x", size: 13, color: C.critical }), error),
        e("button", {
          style: { ...styles.saveBtn, marginTop: 16, ...((saving || saved) ? styles.btnDisabled : {}) },
          disabled: saving || saved, onClick: handleSave
        }, saved ? "Logged ✓" : (saving ? "Saving…" : "Save"))
      )
    );
  }

  // Shows (and, for a trainer/manager, lets you set) the ONE program a specific client is
  // actually following right now — distinct from the full template library in ProgramsPanel,
  // which every trainer can browse and build from. Assigning here is what turns a shared
  // template into "this is Sarah's program."
  // Sept 10 2026, Jimmy: a self-train client's own "request a program" affordance
  // (the Assign button + picker below) only ever lived up in "Your program," well
  // above the fold once someone's scrolled down into "Browse all programs" — each
  // locked card down there just said "pick it above" as plain, non-clickable text.
  // forwardRef + quickPick exposes a way for ProgramsPanel's own browse cards to
  // trigger a pick directly (see the "Request this program" button below), reusing
  // this exact same tested assign logic instead of duplicating it.
  const ClientProgramCard = React.forwardRef(function ClientProgramCard({ clientName, clientId, userId = null, userEmail = null, canAssign = false, isSelfTrain = false, gatePayment = false, appAccessOk = true, paidAccessOk = true, trainerId = null, onAssignmentChange = null }, ref) {
    const [loaded, setLoaded] = useState(false);
    const [assignment, setAssignment] = useState(null);
    const [program, setProgram] = useState(null);
    const [exercises, setExercises] = useState([]);
    const [allPrograms, setAllPrograms] = useState([]);
    const [picking, setPicking] = useState(false);
    const [pickedId, setPickedId] = useState("");
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    // Sept 13 2026, Jimmy: inline "are you sure" instead of window.confirm().
    const [confirmUnassign, setConfirmUnassign] = useState(false);
    // Sept 11 2026: "View full program" on the restyled hero card scrolls
    // down to the existing day-by-day exercise list instead of duplicating it.
    const programDetailRef = useRef(null);
    // Sept 14 2026, Jimmy: which exercise's "Log weight" button was tapped
    // (holds both the exercise row and its day label, for LogProgramWeightModal's
    // context line) — works the same whether this program was bought
    // (self-train, no trainer) or assigned by a trainer, since it's just
    // logging into the client's own workout log either way.
    const [logTarget, setLogTarget] = useState(null);
    // Sept 15 2026, Jimmy: "i want the client to be able to tap on every
    // week like the program the trainer assign so he's doesnt have to
    // scroll all the way down" — same week-chip filter
    // ClientCustomProgramCard already has for a trainer-written program;
    // this card (the shared-catalog "Your program") never had it, so a
    // long multi-week program was one long scroll with no way to jump
    // straight to, say, Week 8. "all" shows every week same as before.
    const [activeWeek, setActiveWeek] = useState("all");
    // Sept 19 2026, walkthrough finding: same one-tap nudge DietPanel
    // already has for a client stuck waiting on their trainer — this card's
    // own "ask your trainer" empty state (below) had no equivalent.
    const [nudgeSent, setNudgeSent] = useState(false);
    function handleNudgeTrainer() {
      if (!trainerId) return;
      notifyTrainer(trainerId, `${clientName || "Your client"} is waiting on a program to be assigned.`);
      setNudgeSent(true);
    }

    useEffect(() => { loadAssignment(); }, [clientName, clientId]);

    // Guards against a dangling week filter (e.g. the program gets
    // reassigned/changed and the previously-selected week label no longer
    // exists), which would otherwise silently show nothing.
    useEffect(() => {
      if (activeWeek !== "all" && !weekGroups().some((w) => w.label === activeWeek)) setActiveWeek("all");
    }, [exercises]);

    async function loadAssignment() {
      // Sept 10 2026: this used to also require clientName truthy — but the
      // actual lookup below keys entirely on clientId, and clientName can be
      // legitimately blank/still-loading for a real client. Requiring it too
      // was silently hiding this whole "request a program" card for anyone
      // it happened to be blank for, with no error and no obvious cause.
      if (!sb || !clientId) { setLoaded(true); return; }
      setLoaded(false);
      const { data: rows } = await sb.from("client_program_assignments").select("*").eq("client_id", clientId).order("assigned_at", { ascending: false }).limit(1);
      const a = rows && rows[0];
      setAssignment(a || null);
      if (onAssignmentChange) onAssignmentChange(a || null);
      if (a) {
        const { data: prog } = await sb.from("training_programs").select("*").eq("id", a.program_id).maybeSingle();
        setProgram(prog || null);
        if (prog) {
          const { data: exRows } = await sb.from("program_exercises").select("*").eq("program_id", prog.id).order("order_index", { ascending: true });
          setExercises(exRows || []);
        } else {
          setExercises([]);
        }
      } else {
        setProgram(null);
        setExercises([]);
      }
      setLoaded(true);
    }

    async function openPicker() {
      // Belt-and-suspenders — the button that calls this is hidden while
      // purchaseLocked, but guard here too in case anything else ever calls it.
      if (purchaseLocked) return;
      setPicking(true);
      setError("");
      setPickedId("");
      if (sb) {
        const { data } = await sb.from("training_programs").select("id, name, style").order("style", { ascending: true }).order("order_index", { ascending: true });
        const list = data || [];
        setAllPrograms(list);
        // A native <select> with no matching option for value="" still visually
        // shows the first option in the list — but our state stays empty until
        // the user actually changes it, so clicking Assign without touching the
        // dropdown looked like it did nothing. Default the picked id to whatever
        // is actually shown so Assign works immediately.
        if (list.length > 0) setPickedId(list[0].id);
      }
    }

    // Sept 10 2026: accepts an explicit programId so a "Request this program"
    // button elsewhere (ProgramsPanel's own browse cards, via the quickPick
    // ref below) can trigger the exact same assign flow directly on one
    // specific card, instead of only ever working through the picker
    // dropdown's own pickedId state. The picker's Assign button still calls
    // this with no argument, which falls back to pickedId exactly as before.
    // Returns true/false so a caller (ProgramsPanel's browse-list "Choose
    // this program" button, via quickPick below) can tell whether a pick
    // actually went through, instead of assuming it always did.
    async function handleAssign(explicitId) {
      const id = explicitId || pickedId;
      if (!id) { setError("Pick a program."); return false; }
      // Sept 18 2026, Jimmy retest: the picker's own "Assign" button and
      // openPicker() both already check purchaseLocked before letting
      // anyone get this far, but the browse-list "Choose this program"
      // button (ProgramsPanel -> handleRequestProgram -> quickPick) called
      // straight into this function with no check at all — a self-train
      // client whose trial AND payment had both lapsed could still request
      // a brand-new program. Same belt-and-suspenders guard as openPicker.
      //
      // Sept 18 2026 retest round 2: this can also be hit by a client still
      // inside their free trial who just hasn't paid the app-access fee
      // yet (purchaseLocked is about payment, not trial expiry) — "lapsed"
      // wrongly implied something that used to work had broken.
      if (purchaseLocked) { setError("Pay to unlock picking a program."); return false; }
      if (!sb) { setError("Backend not configured yet."); return false; }
      setSaving(true);
      setError("");
      if (assignment) await sb.from("client_program_assignments").delete().eq("id", assignment.id);
      const payload = { client_name: clientName, client_id: clientId, program_id: id };
      // Self-train clients only need to pay once per program — if
      // client_payments already has a row for this exact client + program_id
      // (even from an assignment that's since been deleted, e.g. they
      // removed it and are picking it back), this pick comes back already
      // unlocked instead of re-gating something they've genuinely already
      // paid for. Checked by isSelfTrain (a real client property), not
      // gatePayment (which is only true in the client's own view — the
      // manager's assign screen always passes gatePayment=false but still
      // needs this same check when reassigning a self-train client's
      // program). Trainer-owned clients are untouched — paid never gates
      // them either way.
      //
      // Matched by userId (client_payments.user_id, the same real key every
      // payment row is written against everywhere else in this file) —
      // NOT client_name. Two different clients can share the same display
      // name, and matching on the name alone would either wrongly grant one
      // of them free access off the other's payment, or wrongly block a
      // legitimate re-charge after a client renames themselves. If userId
      // isn't available for some reason, this safely skips the check rather
      // than querying on a name — worst case a client is asked to pay again,
      // never wrongly granted free access.
      if (isSelfTrain && userId) {
        const { data: priorPayment } = await sb.from("client_payments").select("id").eq("user_id", userId).eq("program_id", id).limit(1).maybeSingle();
        if (priorPayment) payload.paid = true;
      }
      const { error: err } = await sb.from("client_program_assignments").insert([payload]);
      setSaving(false);
      if (err) { setError("Couldn't assign that program. Try again."); return false; }
      // Notify the client only once this pick is actually usable — a
      // trainer-attached client is never payment-gated, so an assignment IS
      // the unlock; a self-train client only counts as unlocked here if they
      // already had a prior payment for this exact program (payload.paid,
      // set above). If they haven't paid, ProgramRequestRow.handleUnlock is
      // the thing that notifies them once that payment is marked received —
      // notifying here too would tell them it's "ready" before it actually is.
      if (userId && (!isSelfTrain || payload.paid)) {
        const pickedProgram = allPrograms.find((p) => p.id === id);
        notifyClient(userId, `Your program${pickedProgram ? ` "${pickedProgram.name}"` : ""} is ready — check your Programs tab.`);
      }
      setPicking(false);
      setPickedId("");
      // Awaited (not fire-and-forget) so a caller using quickPick via ref —
      // ProgramsPanel's "Request this program" button — can rely on this
      // resolving only once assignment state (and onAssignmentChange) is
      // actually up to date, not just once the insert itself finished.
      await loadAssignment();
      if (onAssignmentChange) onAssignmentChange();
      return true;
    }

    async function handleUnassign() {
      if (!assignment || !sb) return;
      setConfirmUnassign(false);
      setSaving(true);
      await sb.from("client_program_assignments").delete().eq("id", assignment.id);
      setSaving(false);
      loadAssignment();
      if (onAssignmentChange) onAssignmentChange();
    }

    // Sept 15 2026: groups by week_label first, then day_label within it —
    // a plain dayGroups() (day_label only) used to silently MERGE two
    // different weeks' exercises together whenever they reused the same day
    // label (e.g. every week's "Day 1 — Squat"), which is exactly what a
    // duplicated week would do. week_label missing (an older row, or a
    // program with only one week) reads as "Week 1".
    function weekGroups() {
      const byWeek = {};
      const order = [];
      exercises.forEach((r) => {
        const wl = r.week_label || "Week 1";
        if (!byWeek[wl]) { byWeek[wl] = { days: {}, dayOrder: [] }; order.push(wl); }
        const wk = byWeek[wl];
        if (!wk.days[r.day_label]) { wk.days[r.day_label] = []; wk.dayOrder.push(r.day_label); }
        wk.days[r.day_label].push(r);
      });
      return order.map((label) => ({ label, days: byWeek[label].dayOrder.map((d) => ({ label: d, rows: byWeek[label].days[d] })) }));
    }

    // Exposed so ProgramsPanel's own "Request this program" button (on each
    // locked browse card) can trigger a real pick directly, reusing this
    // exact tested handleAssign logic instead of a second copy of it. Called
    // unconditionally, before the loading early-return below, per the rules
    // of hooks.
    React.useImperativeHandle(ref, () => ({ quickPick: (programId) => handleAssign(programId) }));

    if (!loaded) return e("div", { style: styles.empty }, e("p", { style: styles.emptyText }, "Loading program…"));

    // Blocks picking or changing a program at all, before any $35 payment
    // even enters the picture — Jimmy's call (Sept 5 2026): a self-train
    // client must already have this month's $10 app access marked PAID
    // (not just be inside the free trial) before they're allowed to buy a
    // program. Never true for a manager or a trainer-attached client.
    const purchaseLocked = gatePayment && !paidAccessOk;
    const pendingPayment = gatePayment && !(assignment && assignment.paid);
    // The $35 unlocks this program once, but a self-train client's monthly
    // $10 is what keeps it viewable — same rule as Log/Diet. If they've paid
    // for the program but their app access has lapsed, the program re-locks
    // too, and comes back as soon as they're paid up again (no re-buying the
    // program). appAccessOk is always true for managers and trainer-attached
    // clients, so this never affects them.
    const subscriptionLocked = gatePayment && !pendingPayment && !appAccessOk;
    const contentLocked = pendingPayment || subscriptionLocked;

    // Shown instead of the program card's own content whenever picking is
    // true — for BOTH "has a program, tapped Change" and "no program yet,
    // tapped Assign a program". Previously this form only ever rendered
    // appended after the current program's full exercise list, which for a
    // multi-day circuit program could be 30+ rows down — easy to tap
    // "Change" and see nothing happen without scrolling a long way. Putting
    // it right where the program's own content normally sits means it's
    // visible immediately, no scrolling required.
    const pickerForm = e("div", { style: { ...styles.sessionForm, marginTop: program ? 0 : 14 } },
      e("label", { style: styles.formLabel }, "Choose a program"),
      allPrograms.length === 0
        ? e("p", { style: styles.emptyText }, "No programs exist yet — build one in the Programs tab first.")
        : e(Select, { value: pickedId, onChange: setPickedId, options: allPrograms.map((p) => ({ value: p.id, label: `${styleLabel(p.style)} — ${p.name}` })), style: { width: "100%" } }),
      e("div", { style: { display: "flex", gap: 8, marginTop: 12 } },
        // Sept 18 2026 retest round 2: this was `onClick: handleAssign`,
        // which hands handleAssign the raw click SyntheticEvent as its
        // `explicitId` argument (React always passes the event to a
        // directly-referenced handler). Since that event object is truthy,
        // `explicitId || pickedId` picked the EVENT over the actual
        // dropdown selection every time — the insert then failed (an event
        // object isn't a program id) and "Assign" from this picker form
        // could never actually succeed, always landing on the generic
        // "Couldn't assign that program" error. Wrapping in an arrow so no
        // argument is passed and it correctly falls back to pickedId.
        e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(saving ? styles.btnDisabled : {}) }, disabled: saving || allPrograms.length === 0, onClick: () => handleAssign() }, saving ? "Assigning…" : "Assign"),
        e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setPicking(false); setPickedId(""); setError(""); } }, "Cancel")
      )
    );

    const allWeekGroups = weekGroups();
    const groupsToShow = activeWeek === "all" ? allWeekGroups : allWeekGroups.filter((w) => w.label === activeWeek);

    return e("div", null,
      error && e("div", { style: { ...styles.errorBanner, margin: "0 0 12px" } }, e(Icon, { name: "x", size: 13, color: C.critical }), error),
      program
        ? e("div", {
            style: {
              ...styles.programCard, position: "relative", overflow: "hidden",
              // Sept 11 2026, Jimmy: brand-ring "current plan" treatment,
              // matching the reference mockup — only once it's actually
              // live (not mid-pick, not still locked behind payment).
              ...(!contentLocked && !picking ? { boxShadow: `inset 0 0 0 1.5px ${C.brand}, ${C.cardShadow}` } : {})
            }
          },
            e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 } },
              e("div", { style: styles.programHeader },
                e("div", { style: { display: "flex", alignItems: "center", gap: 10 } },
                  !contentLocked && !picking && e("div", { style: styles.planHeroIconWrap }, e(Icon, { name: "dumbbell", size: 16, color: C.brand })),
                  e("div", null,
                    e("span", { style: styles.demoNote }, styleLabel(program.style)),
                    e("span", { style: { ...styles.sectionTitle, display: "block", marginTop: 2 } }, program.name)
                  )
                ),
                // Picking a program (even before paying) used to reveal its
                // full description here immediately — same leak as the
                // browse list, just one screen later. Clamp it the same way
                // while payment/access is locked; it opens up full-width the
                // moment contentLocked clears.
                !picking && program.description && e("p", {
                  style: contentLocked
                    ? { ...styles.profileGoalText, marginTop: 4, display: "-webkit-box", WebkitLineClamp: 3, WebkitBoxOrient: "vertical", overflow: "hidden" }
                    : { ...styles.profileGoalText, marginTop: 4 }
                }, program.description)
              ),
              e("div", { style: { display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 8, flexShrink: 0 } },
                !contentLocked && !picking && e("span", { style: styles.currentBadge }, e(Icon, { name: "check", size: 9, color: C.brandInk }), "CURRENT"),
                canAssign && !picking && e("div", { style: { display: "flex", gap: 8, alignItems: "center" } },
                  // Switching to a different program is a new pick — same
                  // paid-access-required rule as picking one the first time —
                  // so "Change" is hidden while purchaseLocked. Removing the
                  // current pick (trash) stays available either way; it's not
                  // a purchase.
                  !purchaseLocked && e("button", { style: styles.demoLinkBtn, onClick: openPicker }, "Change"),
                  e("button", { style: styles.deleteBtn, onClick: () => setConfirmUnassign(true), "aria-label": "Unassign program" }, e(Icon, { name: "trash", size: 14 }))
                )
              )
            ),
            confirmUnassign && e("div", { style: { ...styles.deleteConfirmBar, flexDirection: "column", alignItems: "stretch", gap: 8, marginTop: 10 } },
              e("span", { style: styles.deleteConfirmText },
                isSelfTrain
                  ? `Remove this program? ${gatePayment ? "You'll" : "They'll"} lose access to it. Picking it again later won't ask for payment again, but a different one will.`
                  : "Remove this program? They'll lose access to it until it's assigned again."
              ),
              e("div", { style: { display: "flex", gap: 8 } },
                e("button", { style: { ...styles.confirmCancelBtn, flex: 1 }, onClick: () => setConfirmUnassign(false) }, "Cancel"),
                e("button", { style: { ...styles.confirmDangerBtn, flex: 1 }, onClick: handleUnassign }, "Remove")
              )
            ),
            !contentLocked && !picking && allWeekGroups.length > 0 && e("button", {
              style: { ...styles.ghostPillBtn, marginTop: 12 },
              onClick: () => programDetailRef.current && programDetailRef.current.scrollIntoView({ behavior: "smooth", block: "start" })
            }, "View full program", e(Icon, { name: "chevron", size: 13, color: C.ink, strokeWidth: 2.4 })),
            picking
              ? e("div", { style: { marginTop: 16 } }, pickerForm)
              : (pendingPayment
                  ? e("div", { style: { ...styles.empty, marginTop: 16, flexDirection: "column", alignItems: "center", gap: 8 } },
                      e(Icon, { name: "lock", size: 20, color: C.ink3 }), e("p", { style: styles.emptyText }, "Pay below to unlock this program."),
                      // Same real stepper as the app-access lock screens — the
                      // client can mark "I've sent the payment" and then see
                      // "Under review" right here instead of a static line
                      // with no way to tell it went anywhere. Context is keyed
                      // per program (program.id), separate from the app-access
                      // claim below, since a client can owe both at once.
                      e(PaymentStatusStepper, { email: userEmail, context: `program_${program.id}`, amount: PROGRAM_PRICE, approvedCopy: "Approved — unlocked" })
                    )
                  : subscriptionLocked
                  ? e("div", { style: { ...styles.empty, marginTop: 16, flexDirection: "column", alignItems: "center", gap: 8 } },
                      e(Icon, { name: "lock", size: 20, color: C.ink3 }), e("p", { style: styles.emptyText }, `Your $${PROGRAM_PRICE} program is on hold — pay this month's $${SELF_TRAIN_MONTHLY_PRICE} app access to see it again.`),
                      // Same claim as the Log/Diet app-access lock screen
                      // (context "self_train_access") — it's the same $/month
                      // payment, so marking it sent on either screen clears
                      // both.
                      e(PaymentStatusStepper, { email: userEmail, context: "self_train_access", amount: SELF_TRAIN_MONTHLY_PRICE, approvedCopy: "Approved — unlocked" })
                    )
                  : e("div", { ref: programDetailRef },
                      // Sept 15 2026, Jimmy: same "press the week and see
                      // the workout" chip row as the trainer-written
                      // program below — jumping to a specific week is one
                      // tap instead of a scroll past every week before it.
                      allWeekGroups.length > 1 && e("div", { style: { display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 16 } },
                        [{ label: "all", text: "All weeks" }, ...allWeekGroups.map((w) => ({ label: w.label, text: w.label }))].map((opt) => {
                          const active = activeWeek === opt.label;
                          return e("button", {
                            key: opt.label, type: "button", onClick: () => setActiveWeek(opt.label),
                            style: {
                              display: "inline-flex", alignItems: "center", background: active ? C.brandSoft : "transparent",
                              color: active ? C.brand : C.ink3, border: `1px solid ${active ? withAlpha(C.brand, 0.4) : C.cardBorder}`,
                              borderRadius: 20, padding: "6px 12px", fontFamily: "'Inter', sans-serif", fontSize: 12.5, fontWeight: 700,
                              cursor: "pointer", whiteSpace: "nowrap"
                            }
                          }, opt.text);
                        })
                      ),
                      groupsToShow.map((week) => e("div", { key: week.label, style: { marginTop: 16 } },
                        e("div", { style: { ...styles.sectionTitle, fontSize: 13.5 } }, week.label),
                        week.days.map((day) => e("div", { key: day.label, style: { marginTop: 10, marginLeft: 8 } },
                          e("div", { style: styles.dayHead }, day.label),
                          e("div", { style: { display: "flex", flexDirection: "column", gap: 8, marginTop: 8 } },
                            day.rows.map((ex) => e(ProgramExerciseRow, { key: ex.id, ex, canManage: false, onEdit: () => {}, onDelete: () => {}, onLogWeight: () => setLogTarget({ ex, contextLabel: `${program.name} — ${week.label} · ${day.label}` }) }))
                          )
                        ))
                      ))
                    )
                ),
            !contentLocked && !picking && e(ProgramWatermark, { label: clientName }),
            logTarget && e(LogProgramWeightModal, {
              ex: logTarget.ex, clientId, clientName, contextLabel: logTarget.contextLabel,
              onClose: () => setLogTarget(null)
            })
          )
        : e("div", { style: styles.empty }, e(ProgramsEmptyArt, {}), e("p", { style: { ...styles.emptyText, ...(!canAssign && !isSelfTrain && !nudgeSent ? { marginBottom: 8 } : {}) } },
            canAssign
              ? (purchaseLocked
                  // Sept 13 2026, Jimmy: "to be clear that the $10 is
                  // subscription before he buys the program" — a
                  // self-train client hits this even mid-free-trial (see
                  // the purchaseLocked rule above: paid access, not just
                  // "in trial", is required before picking a program), so
                  // without this the $10 read as if it were the program's
                  // price. Spelled out as the recurring monthly app
                  // subscription, separate from the program itself.
                  ? `This $${SELF_TRAIN_MONTHLY_PRICE} is your monthly app subscription — not the program itself. It needs to be paid first, even while your free trial is still running, before you can pick a program. Pay below, then come back here.`
                  : gatePayment ? `No program picked yet — browse below, choose one, then pay to unlock it ($${PROGRAM_PRICE}).` : "No program assigned yet.")
              : (isSelfTrain ? "No program assigned yet — pay to unlock the program library." : "No program assigned yet — ask your trainer.")
          ),
          // Sept 19 2026, walkthrough fix: same one-tap nudge DietPanel
          // already has — only for the trainer-attached case (the only one
          // with a real trainer to nudge; isSelfTrain has no trainer,
          // canAssign is a manager viewing a client, not the client itself).
          !canAssign && !isSelfTrain && trainerId && (!nudgeSent
            ? e("button", { type: "button", style: { ...styles.demoLinkBtn, padding: "0" }, onClick: handleNudgeTrainer }, "Nudge my trainer →")
            : nudgeSent && e("p", { style: { ...styles.emptyText, fontSize: 11.5, color: C.good } }, "Nudge sent — your trainer's been notified.")),
          purchaseLocked && e(WhishPayBox, { amount: SELF_TRAIN_MONTHLY_PRICE, note: "which is your monthly app subscription, then wait for JimFit to confirm — programs unlock once you're paid up" })
          ),
      // "Assign a program" reads like manager/trainer language when it's a
      // self-training client picking one for themselves — same button and
      // handler, just a wording swap based on who's looking at it.
      canAssign && !program && !picking && !purchaseLocked && e("button", { style: { ...styles.newBtn, marginTop: 14 }, onClick: openPicker }, e(Icon, { name: "calendar", size: 15 }), isSelfTrain ? "Choose a program" : "Assign a program"),
      canAssign && !program && picking && pickerForm
    );
  });

  // Real 3-step payment status: "Send payment" (with an "I've sent it"
  // button that records a real timestamp), "Under review" (the natural
  // resting state once sent but not yet confirmed), and "Approved" — which,
  // by definition, is never actually seen as done from in here, since the
  // whole locked screen this sits on disappears the moment a trainer/
  // manager confirms it. It stays visible as the pending next step, same as
  // the mockup, never marked complete on this screen.
  function PaymentStatusStepper({ email, context, amount, approvedCopy }) {
    const [claim, setClaim] = useState(null);
    const [loaded, setLoaded] = useState(false);
    const [submitting, setSubmitting] = useState(false);

    useEffect(() => {
      let cancelled = false;
      setLoaded(false);
      fetchLatestPaymentClaim(email, context).then((row) => {
        if (!cancelled) { setClaim(row); setLoaded(true); }
      });
      return () => { cancelled = true; };
    }, [email, context]);

    const isFresh = !!claim && (Date.now() - new Date(claim.submitted_at).getTime()) < PAYMENT_CLAIM_FRESH_MS;

    async function handleSubmit() {
      setSubmitting(true);
      const row = await submitPaymentClaim(email, context);
      setSubmitting(false);
      if (row) setClaim(row);
    }

    // Sept 13 2026, Jimmy: "when i unlock and buy its something else" — swap
    // the old 3-item vertical stepper list for jimfit-flow_15.html's compact
    // readout: title, pay box, one full-width action button that turns into
    // a disabled "Marked as sent" confirmation, then a small 3-dot progress
    // row with a single line of status copy underneath. Same underlying
    // data (isFresh/claim/handleSubmit) — only the layout changed.
    return e("div", { style: { width: "100%", marginTop: 4 } },
      e("div", { style: styles.stepperTitle }, "Send payment via Whish"),
      e(WhishPayBox, { amount }),
      e("button", {
        style: { ...styles.saveBtn, marginTop: 10, width: "100%", ...((isFresh || submitting || !loaded) ? styles.btnDisabled : {}) },
        disabled: isFresh || submitting || !loaded,
        onClick: handleSubmit
      }, submitting ? "Marking as sent…" : isFresh ? "Marked as sent ✓" : "I've sent the payment"),
      e("div", { style: styles.stepperDotsRow },
        e("span", { style: { ...styles.stepperDotSmall, ...styles.stepperDotSmallLit } }),
        e("span", { style: { ...styles.stepperDotSmall, ...(isFresh ? styles.stepperDotSmallLit : {}) } }),
        e("span", { style: styles.stepperDotSmall })
      ),
      // Sept 13 2026, Jimmy: "marked it as yellow here also" — same amber
      // "pending" treatment as the trainer-request banner (C.warning),
      // applied to the "sent, waiting on us to confirm" line specifically —
      // the "send the payment" instructions below it (isFresh false) aren't
      // a pending state, so those stay the plain neutral color.
      e("p", { style: { ...styles.stepperHintLine, ...(isFresh ? { color: C.warning } : {}) } },
        isFresh
          ? `Sent ${fmtDateTimeMed(claim.submitted_at)} — usually confirmed within a day.`
          : "Send the payment above, then mark it as sent."
      ),
      isFresh && e("p", { style: { ...styles.stepperHintLine, marginTop: 4, color: C.ink3, fontSize: 11 } }, approvedCopy || "We'll notify you the moment it's approved.")
    );
  }

export { EditableStat, ExercisePicker, VoiceMicButton, SmartVoiceEntryButton, ExerciseIcon, ExerciseDemo, TurnstileWidget, ProgramExerciseRow, LogProgramWeightModal, ClientProgramCard, PaymentStatusStepper };
